// ==========================================
// SMART DOOR ACCESS CONTROL - ESP32
// Wi-Fi + HTTP + Physical LED / Wokwi
// ==========================================

#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>

// ==========================================
// HARDWARE MODE
// ==========================================

// 0 = Wokwi: 2 LEDs + Servo
// 1 = Physical: 1 common-anode LED

#define HARDWARE_MODE_WOKWI 0
#define HARDWARE_MODE_PHYSICAL 1

// Select physical mode by default
// #define HARDWARE_MODE HARDWARE_MODE_WOKWI
#define HARDWARE_MODE HARDWARE_MODE_PHYSICAL

// ==========================================
// WI-FI CONFIGURATION
// ==========================================

// Enter your Wi-Fi name and password here

const char* WIFI_SSID = "Night City";
const char* WIFI_PASSWORD = "5N4EopsCT";

const char* HOSTNAME = "smartdoor";

// ==========================================
// HTTP SERVER
// ==========================================

WebServer server(80);

bool serverStarted = false;
bool mdnsStarted = false;

unsigned long lastWiFiAttempt = 0;
const unsigned long WIFI_RECONNECT_INTERVAL = 10000;

// ==========================================
// PIN CONFIGURATION
// ==========================================

#define GREEN_LED 25
#define RED_LED 26
#define SERVO_PIN 18

#define STATUS_LED 25

// ==========================================
// SERVO CONFIGURATION
// ==========================================

#define SERVO_LOCKED 0
#define SERVO_UNLOCKED 90

// ==========================================
// LED BLINKING CONFIGURATION
// ==========================================

const unsigned long BLINK_INTERVAL = 200;

bool deniedBlinkActive = false;
bool deniedBlinkState = false;

unsigned long lastBlinkTime = 0;
int blinkTransitions = 0;

// ==========================================
// PHYSICAL LED CONTROL
// ==========================================

// Common anode:
// LOW = LED ON
// HIGH = LED OFF

void physicalLedOn() {
    digitalWrite(STATUS_LED, LOW);
}

void physicalLedOff() {
    digitalWrite(STATUS_LED, HIGH);
}

// ==========================================
// HARDWARE CONTROL
// ==========================================

void setDoorPosition(int angle) {

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    int pulseWidth = map(angle, 0, 180, 500, 2500);
    uint32_t duty = (uint32_t)pulseWidth * 65535 / 20000;

    ledcWrite(SERVO_PIN, duty);

#endif
}

void stopDeniedBlink() {

    deniedBlinkActive = false;
    deniedBlinkState = false;
    blinkTransitions = 0;
}

// ==========================================
// LOCKED STATE
// ==========================================

void setLockedState() {

    stopDeniedBlink();

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    digitalWrite(GREEN_LED, LOW);
    digitalWrite(RED_LED, LOW);

    setDoorPosition(SERVO_LOCKED);

#else

    physicalLedOff();

#endif
}

// ==========================================
// GRANTED STATE
// ==========================================

void setGrantedState() {

    stopDeniedBlink();

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    digitalWrite(GREEN_LED, HIGH);
    digitalWrite(RED_LED, LOW);

    setDoorPosition(SERVO_UNLOCKED);

#else

    physicalLedOn();

#endif
}

// ==========================================
// DENIED STATE
// ==========================================

void setDeniedState() {

    stopDeniedBlink();

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    digitalWrite(GREEN_LED, LOW);
    setDoorPosition(SERVO_LOCKED);

#else

    physicalLedOn();

#endif

    deniedBlinkActive = true;
    deniedBlinkState = true;

    lastBlinkTime = millis();
    blinkTransitions = 0;

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    digitalWrite(RED_LED, HIGH);

#endif
}

// ==========================================
// DENIED ACCESS BLINKING
// ==========================================

void updateDeniedBlink() {

    if (!deniedBlinkActive) {
        return;
    }

    if (millis() - lastBlinkTime >= BLINK_INTERVAL) {

        lastBlinkTime = millis();

        deniedBlinkState = !deniedBlinkState;
        blinkTransitions++;

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

        digitalWrite(RED_LED, deniedBlinkState);

#else

        if (deniedBlinkState) {
            physicalLedOn();
        } else {
            physicalLedOff();
        }

#endif

        if (blinkTransitions >= 10) {

            stopDeniedBlink();

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

            digitalWrite(RED_LED, LOW);

#else

            physicalLedOff();

#endif
        }
    }
}

// ==========================================
// COMMAND HANDLER
// ==========================================

String executeCommand(String command) {

    command.trim();

    if (command == "GRANTED" || command == "UNLOCK") {

        setGrantedState();
        Serial.println("ACCESS GRANTED");

        return "ACCESS GRANTED";
    }

    else if (command == "DENIED") {

        setDeniedState();
        Serial.println("ACCESS DENIED");

        return "ACCESS DENIED";
    }

    else if (command == "LOCK" || command == "OFF") {

        setLockedState();
        Serial.println("DOOR LOCKED");

        return "DOOR LOCKED";
    }

    return "UNKNOWN COMMAND";
}

// ==========================================
// HTTP ROUTES
// ==========================================

void setupHTTPRoutes() {

    server.on("/", HTTP_GET, []() {

        server.send(200, "text/plain",
                    "SMART DOOR SYSTEM ONLINE");
    });

    server.on("/discover", HTTP_GET, []() {

        String json = "{";
        json += "\"device\":\"SMART_DOOR\",";
        json += "\"status\":\"ONLINE\",";
        json += "\"ip\":\"" + WiFi.localIP().toString() + "\",";
        json += "\"hostname\":\"smartdoor.local\"";
        json += "}";

        server.send(200, "application/json", json);
    });

    server.on("/GRANTED", HTTP_GET, []() {

        String result = executeCommand("GRANTED");
        server.send(200, "text/plain", result);
    });

    server.on("/DENIED", HTTP_GET, []() {

        String result = executeCommand("DENIED");
        server.send(200, "text/plain", result);
    });

    server.on("/LOCK", HTTP_GET, []() {

        String result = executeCommand("LOCK");
        server.send(200, "text/plain", result);
    });

    server.on("/OFF", HTTP_GET, []() {

        String result = executeCommand("OFF");
        server.send(200, "text/plain", result);
    });

    server.onNotFound([]() {

        server.send(404, "text/plain", "ENDPOINT NOT FOUND");
    });
}

// ==========================================
// WI-FI CONNECTION
// ==========================================

void connectWiFi() {

    Serial.println();
    Serial.println("CONNECTING TO WIFI...");

    WiFi.mode(WIFI_STA);
    WiFi.setHostname(HOSTNAME);
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

    lastWiFiAttempt = millis();
}

// ==========================================
// SETUP
// ==========================================

void setup() {

    Serial.begin(115200);

#if HARDWARE_MODE == HARDWARE_MODE_WOKWI

    pinMode(GREEN_LED, OUTPUT);
    pinMode(RED_LED, OUTPUT);

    digitalWrite(GREEN_LED, LOW);
    digitalWrite(RED_LED, LOW);

    ledcAttach(SERVO_PIN, 50, 16);
    setDoorPosition(SERVO_LOCKED);

    Serial.println("SYSTEM READY - WOKWI MODE");

#else

    pinMode(STATUS_LED, OUTPUT);
    physicalLedOff();

    Serial.println("SYSTEM READY - PHYSICAL MODE");

#endif

    setupHTTPRoutes();

    connectWiFi();

    // Wait up to 15 seconds for initial Wi-Fi connection

    unsigned long startAttempt = millis();

    while (WiFi.status() != WL_CONNECTED &&
           millis() - startAttempt < 15000) {

        delay(500);
        Serial.print(".");
    }

    Serial.println();

    if (WiFi.status() == WL_CONNECTED) {

        Serial.println("WIFI CONNECTED");

        Serial.print("ESP32 IP ADDRESS: ");
        Serial.println(WiFi.localIP());

        server.begin();
        serverStarted = true;

        Serial.println("HTTP SERVER STARTED");

        if (MDNS.begin(HOSTNAME)) {

            mdnsStarted = true;
            MDNS.addService("http", "tcp", 80);

            Serial.println("MDNS STARTED");
            Serial.println("ADDRESS: http://smartdoor.local");
        }
    }

    else {

        Serial.println("WIFI CONNECTION FAILED");
        Serial.println("WILL RETRY AUTOMATICALLY");
    }
}

// ==========================================
// MAIN LOOP
// ==========================================

void loop() {

    updateDeniedBlink();

    // Handle HTTP requests

    if (WiFi.status() == WL_CONNECTED) {

        if (!serverStarted) {

            server.begin();
            serverStarted = true;

            Serial.println("HTTP SERVER STARTED");
        }

        if (!mdnsStarted) {

            if (MDNS.begin(HOSTNAME)) {

                mdnsStarted = true;
                MDNS.addService("http", "tcp", 80);

                Serial.println("MDNS STARTED");
            }
        }

        server.handleClient();
    }

    // Reconnect Wi-Fi if disconnected

    else {

        if (serverStarted) {
            server.stop();
            serverStarted = false;
        }

        mdnsStarted = false;

        if (millis() - lastWiFiAttempt >= WIFI_RECONNECT_INTERVAL) {

            Serial.println("RECONNECTING TO WIFI...");

            WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
            lastWiFiAttempt = millis();
        }
    }

    // Handle Serial Monitor commands

    if (Serial.available()) {

        String command = Serial.readStringUntil('\n');
        command.trim();

        executeCommand(command);
    }
}
